CREATE VIEW "EXT"."CSA_RPP_RESUMEN_SVW" ( "TIPO_INFORME", "PERIODSEQ", "POSITIONSEQ", "PERIODO", "PERIODO_FORMATO", "COD_AGENTE", "NOMBRE_AGENTE", "NIF", "TIPO_AGENTE", "POL_CORR", "PRIMAS", "PAGOS", "SOLO_DIFERENCIAS", "FEC_ACTUALIZACION" ) AS (SELECT "TIPO_INFORME" , "PERIODSEQ" , "POSITIONSEQ" , "PERIODO" , "PERIODO_FORMATO" , "COD_AGENTE" , "NOMBRE_AGENTE" , "NIF" , "TIPO_AGENTE" , "POL_CORR" , "PRIMAS" , "PAGOS" , "SOLO_DIFERENCIAS" , "FEC_ACTUALIZACION" 
	FROM EXT.OUT_RPP_RESUMEN_FINAL_REP
	WHERE TIPO_INFORME = 'CIERRE'
	AND PERIODSEQ IN (SELECT PERIODSEQ FROM EXT.LIB_CREAR_TABLAS:N_MESES(13))) WITH  STRUCTURED PRIVILEGE CHECK